import math, re
from collections import Counter
notes = {
    "python": "A Python function accepts inputs and returns a result.",
    "evaluation": "Keep test data separate when selecting a model.",
    "neuron": "A neuron applies weights and a bias before an activation.",
    "privacy": "Collect only the data required for a stated purpose.",
}
def tokens(text):
    return re.findall(r"[a-z]+", text.lower())
corpus = {key: tokens(text) for key, text in notes.items()}
vocabulary = sorted(set(word for words in corpus.values() for word in words))
idf = {w: math.log((1+len(notes))/(1+sum(w in d for d in corpus.values())))+1 for w in vocabulary}
def vector(text):
    counts = Counter(tokens(text))
    return [counts[w]*idf[w] for w in vocabulary]
def cosine(a, b):
    denominator = math.sqrt(sum(x*x for x in a)*sum(x*x for x in b))
    return sum(x*y for x, y in zip(a, b))/denominator if denominator else 0.
index = {key: vector(text) for key, text in notes.items()}
def search(question, limit=2):
    query = vector(question)
    ranked = sorted(((cosine(query, v), key) for key, v in index.items()), reverse=True)
    return [{"id": key, "score": round(score, 3), "passage": notes[key]}
            for score, key in ranked[:limit] if score > 0]
for question in ["Python function", "test data model", "galactic weather"]:
    print(question, "->", search(question) or "No matching passage")
